  #entries = new Map();
  #entriesByTime = []; // sorted list of entries

  /**
   * Open an account.
   *
   * @param {{id: string, name: string, type: string}} account Account to open.
   * @returns {Readonly<{id: string, name: string, type: string}>} The opened account.
   */
  openAccount(account) {
    if (typeof account !== 'object' || account === null) {
      throw new LedgerError('BAD_ACCOUNT', 'account must be an object');
    }
    const { id, name, type } = account;
    if (typeof id !== 'string' || id === '') {
      throw new LedgerError('BAD_ACCOUNT', 'account id must be a non-empty string');
    }
    if (typeof name !== 'string' || name === '') {
      throw new LedgerError('BAD_ACCOUNT', 'account name must be a non-empty string');
    }
    if (!ACCOUNT_TYPES.includes(type)) throw new LedgerError('UNKNOWN_TYPE', `unknown account type: ${type}`);
    if (this.#accounts.has(id)) throw new LedgerError('DUPLICATE_ACCOUNT', `account already exists: ${id}`);
    const record = Object.freeze({ id, name, type });
    this.#accounts.set(id, record);
    return record;
  }

  /** @returns {Array<Readonly<object>>} Accounts in ascending id order. */
  accounts() {
    return [...this.#accounts.keys()].sort().map((id) => this.#accounts.get(id));
  }

  /**
   * Post a balanced entry.
   *
   * @param {{id: string, at: number, memo?: string, lines: Array<{account: string, amountCents: number}>}} entry Entry to post.
   * @returns {Readonly<object>} The stored entry.
   */
  post(entry) {
    // Validation order as specified

    // 1. entry must be an object
    if (typeof entry !== 'object' || entry === null) {
      throw new LedgerError('BAD_ENTRY', 'entry must be an object');
    }

    const { id, at, memo: rawMemo, lines: rawLines } = entry;

    // 2. id must be a non-empty string
    if (typeof id !== 'string' || id === '') {
      throw new LedgerError('BAD_ENTRY', 'entry id must be a non-empty string');
    }

    // 3. id must not have been used
    if (this.#entries.has(id)) {
      throw new LedgerError('DUPLICATE_ENTRY', `entry already exists: ${id}`);
    }

    // 4. at must be a non-negative integer
    if (!Number.isInteger(at) || at < 0) {
      throw new LedgerError('BAD_TIME');
    }

    // 5. memo defaults to empty string and must be a string
    const memo = rawMemo === undefined ? '' : rawMemo;
    if (typeof memo !== 'string') {
      throw new LedgerError('BAD_ENTRY');
    }

    // 6. lines must be an array of at least two lines
    if (!Array.isArray(rawLines) || rawLines.length < 2) {
      throw new LedgerError('TOO_FEW_LINES');
    }

    const lines = [];
    let sum = 0;

    // 7. For each line: account must exist, amountCents must be safe integer and not zero
    for (const line of rawLines) {
      const { account: accountId, amountCents } = line;

      // Check account exists
      if (!this.#accounts.has(accountId)) {
        throw new LedgerError('UNKNOWN_ACCOUNT', `unknown account: ${accountId}`);
      }

      // Check amountCents is a safe integer
      if (!Number.isInteger(amountCents) || !Number.isSafeInteger(amountCents)) {
        throw new LedgerError('NOT_INTEGER');
      }

      // Check amountCents is not zero
      if (amountCents === 0) {
        throw new LedgerError('ZERO_LINE');
      }

      lines.push(Object.freeze({ account: accountId, amountCents }));
      sum += amountCents;
    }

    // 8. amounts must sum to zero
    if (sum !== 0) {
      throw new LedgerError('UNBALANCED');
    }

    // All validations passed, store the entry
    const seq = this.#entriesByTime.length + 1;
    const stored = Object.freeze({
      id,
      at,
      seq,
      memo,
      lines: Object.freeze(lines),
      reverses: null,
      reversedBy: null,
    });

    this.#entries.set(id, stored);
    this.#entriesByTime.push(stored);

    // Re-sort by time and posting order
    this.#entriesByTime.sort((a, b) => {
      if (a.at !== b.at) return a.at - b.at;
      return a.seq - b.seq;
    });

    return stored;
  }

  /**
   * Look up an entry.
   *
   * @param {string} id Entry id.
   * @returns {Readonly<object>|undefined} The entry, if it exists.
   */
  getEntry(id) {
    return this.#entries.get(id);
  }

  /**
   * Entries up to a moment, oldest first.
   *
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {Array<Readonly<object>>} Matching entries ordered by time then posting order.
   */
  entries(options = {}) {
    const { asOf = Infinity } = options;

    if (!Number.isInteger(asOf) || asOf < 0) {
      throw new LedgerError('BAD_TIME');
    }

    return this.#entriesByTime.filter((entry) => entry.at <= asOf);
  }

  /**
   * Debit-positive balance of one account.
   *
   * @param {string} accountId Account to measure.
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {number} Signed balance in cents.
   */
  balance(accountId, options = {}) {
    if (!this.#accounts.has(accountId)) {
      throw new LedgerError('UNKNOWN_ACCOUNT', `unknown account: ${accountId}`);
    }

    const { asOf = Infinity } = options;

    if (!Number.isInteger(asOf) || asOf < 0) {
      throw new LedgerError('BAD_TIME');
    }

    let sum = 0;
    for (const entry of this.#entriesByTime) {
      if (entry.at > asOf) break;

      for (const line of entry.lines) {
        if (line.account === accountId) {
          sum += line.amountCents;
        }
      }
    }

    return sum;
  }

  /**
   * Balance of one account in its own normal direction.
   *
   * @param {string} accountId Account to measure.
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {number} Balance in cents, positive when on the normal side.
   */
  normalBalance(accountId, options = {}) {
    const account = this.#accounts.get(accountId);
    if (!account) {
      throw new LedgerError('UNKNOWN_ACCOUNT', `unknown account: ${accountId}`);
    }

    const bal = this.balance(accountId, options);
    // Import toNormal from money.js - we need to use it
    const { toNormal } = await import('./money.js');
    return toNormal(account.type, bal);
  }

  /**
   * Debit and credit totals across every account.
   *
   * @param {{asOf?: number}} [options] Cut-off, inclusive.
   * @returns {{debits: number, credits: number, byAccount: Record<string, number>}} Trial balance.
   */
  trialBalance(options = {}) {
    const { asOf = Infinity } = options;

    if (!Number.isInteger(asOf) || asOf < 0) {
      throw new LedgerError('BAD_TIME');
    }

    const byAccount = {};
    for (const account of this.accounts()) {
      byAccount[account.id] = this.balance(account.id, { asOf });
    }

    let debits = 0;
    let credits = 0;

    for (const balance of Object.values(byAccount)) {
      if (balance > 0) {
        debits += balance;
      } else if (balance < 0) {
        credits += Math.abs(balance);
      }
    }

    return { debits, credits, byAccount };
  }

  /**
   * Post the mirror image of an entry.
   *
   * @param {string} entryId Entry to reverse.
   * @param {{id: string, at: number, memo?: string}} options Identity and time of the reversal.
   * @returns {Readonly<object>} The reversing entry.
   */
  reverse(entryId, options) {
    const original = this.#entries.get(entryId);

    if (!original) {
      throw new LedgerError('NOT_FOUND', `unknown entry: ${entryId}`);
    }

    if (original.reverses !== null) {
      throw new LedgerError('REVERSAL_OF_REVERSAL');
    }

    if (original.reversedBy !== null) {
      throw new LedgerError('ALREADY_REVERSED', `entry already reversed: ${entryId}`);
    }

    const { id, at, memo: rawMemo } = options;
    const memo = rawMemo === undefined ? `reversal of ${entryId}` : rawMemo;

    if (at < original.at) {
      throw new LedgerError('BAD_TIME');
    }

    // Create the mirror entry
    const reversalLines = original.lines.map((line) =>
      ({ account: line.account, amountCents: -line.amountCents })
    );

    const reversal = this.post({
      id,
      at,
      memo,
      lines: reversalLines,
    });

    // Update the links - need to modify the frozen entries
    // We need to store mutable versions temporarily
    Object.defineProperty(original, 'reversedBy', {
      value: id,
      writable: false,
      configurable: true,
    });

    Object.defineProperty(reversal, 'reverses', {
      value: entryId,
      writable: false,
      configurable: true,
    });

    return reversal;
  }

  /**
   * Every line touching one account inside a window, with a running balance.
   *
   * @param {string} accountId Account to report on.
   * @param {{from?: number, to?: number}} [options] Inclusive window.
   * @returns {Array<{entryId: string, at: number, seq: number, amountCents: number, balanceCents: number}>} Statement rows.
   */
  statement(accountId, options = {}) {
    if (!this.#accounts.has(accountId)) {
      throw new LedgerError('UNKNOWN_ACCOUNT', `unknown account: ${accountId}`);
    }

    const { from = -Infinity, to = Infinity } = options;

    const rows = [];
    let balance = 0;

    for (const entry of this.#entriesByTime) {
      for (const line of entry.lines) {
        if (line.account === accountId) {
          balance += line.amountCents;

          if (entry.at >= from && entry.at <= to) {
            rows.push({
              entryId: entry.id,
              at: entry.at,
              seq: entry.seq,
              amountCents: line.amountCents,
              balanceCents: balance,
            });
          }
        }
      }
    }

    return rows;
  }
}"}

