   * Create an entry object with reversal info merged in.
   */
  #withReversalInfo(baseEntry) {
    const reversalInfo = this.#reversalInfo.get(baseEntry.id);
    if (!reversalInfo) return baseEntry;
    return Object.freeze({
      ...baseEntry,
      reverses: reversalInfo.reverses,
      reversedBy: reversalInfo.reversedBy,
    });
  }

  /**
   * Post a balanced entry.
   *
   * @param {{id: string, at: number, memo?: string, lines: Array<{account: string, amountCents: number}>}} entry Entry to post.
   * @returns {Readonly<object>} The stored entry.
   */
