    // Validation order as specified

    // 1. entry must be an object
    if (typeof entry !== 'object' || entry === null) {
      throw new LedgerError('BAD_ENTRY', 'entry must be an object');
    }

    const { id, at, memo: rawMemo, lines: rawLines } = entry;

    // 2. id must be a non-empty string
    if (typeof id !== 'string' || id === '') {
      throw new LedgerError('BAD_ENTRY', 'entry id must be a non-empty string');
    }

    // 3. id must not have been used
    if (this.#entries.has(id)) {
      throw new LedgerError('DUPLICATE_ENTRY', `entry already exists: ${id}`);
    }

    // 4. at must be a non-negative integer
    if (!Number.isInteger(at) || at < 0) {
      throw new LedgerError('BAD_TIME');
    }

    // 5. memo defaults to empty string and must be a string
    const memo = rawMemo === undefined ? '' : rawMemo;
    if (typeof memo !== 'string') {
